import {readProgression,DEFAULT_PROGRESSION,progressionKey} from './progression.js';
import {actionFor} from './handling-profile.js';
import {handlingRules,handlingKey,fallSummary} from './handling-profile.js';
import {createChallenge,stepChallenge,challengePair,standings,pressureAt,TIMED_MS,breakerRateAt} from './challenge.js';
import {drawBoard,drawNext} from './render.js';
import {OPPONENTS,botProfile,planMove} from './ai.js';
const DT=1000/60,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),clock=ms=>{const s=Math.max(0,Math.ceil(ms/1000));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;};
export function createChallengeUI({host,prefs,read,save,sound,showSettings,getPool,showPool,showProgression}){
 const $=q=>host.querySelector(q),$$=q=>[...host.querySelectorAll(q)],lifecycle=new AbortController(),held=new Map();
 let run=null,paused=false,disposed=false,raf=0,last=0,acc=0,countdown=0,actions=[],workers=[],brains=[],finishedSaved=false,session=0;
 let difficulty=['easy','medium','hard'].includes(read('challenge-difficulty','medium'))?read('challenge-difficulty','medium'):'medium',runKey=null;
 let mode='timed',players=1,seed=crypto.getRandomValues(new Uint32Array(1))[0];
 const runs=read('challenge-runs',[]),history=Array.isArray(runs)?runs:[],bests=read('challenge-bests',{})??{};
 const key=()=>runKey??[mode,players,players===4?difficulty:'solo','v3',handlingKey(prefs.rules),JSON.stringify(getPool().map(p=>[p.id,p.rows])),progressionKey(mode==='endless'?readProgression(read('endless-progression',null)):DEFAULT_PROGRESSION)].join(':');
 const set=(selector,value)=>{const el=$(selector);if(el&&el.textContent!==String(value))el.textContent=String(value);};
 const stopWorkers=()=>{workers.forEach(w=>w?.terminate());workers=[];};
 function setup(){stopWorkers();run=null;runKey=null;held.clear();actions=[];paused=false;
 host.innerHTML=`<section class="room-heading"><div><p class="eyebrow">FREE-FOR-ALL</p><h1>Four boards, one table.</h1></div></section><div class="challenge-setup"><section class="panel challenge-options"><p class="eyebrow">CHOOSE A CHALLENGE</p><div class="challenge-modes"><button data-challenge-mode="timed" class="${mode==='timed'?'selected':''}"><strong>Two-minute rush</strong><span>Score as much as you can before the bell.</span><b>2:00</b></button><button data-challenge-mode="endless" class="${mode==='endless'?'selected':''}"><strong>Endless survival</strong><span>Keep clearing as the pressure rises.</span><b>∞</b></button></div><label class="field-label">Players<select id="challenge-players"><option value="1" ${players===1?'selected':''}>Solo challenge</option><option value="4" ${players===4?'selected':''}>Free-for-all · you + 3 AI</option></select></label><label class="field-label" ${players===1?'hidden':''}>AI difficulty<select id="challenge-difficulty">${['easy','medium','hard'].map(d=>`<option value="${d}" ${d===difficulty?'selected':''}>${d[0].toUpperCase()+d.slice(1)}</option>`).join('')}</select></label><button id="challenge-settings" class="text-button">Controls & feel</button><button id="challenge-pool" class="text-button">Pattern pool</button><p id="challenge-pool-summary" class="fine-print"></p><button id="challenge-progression" class="text-button" ${mode==='endless'?'':'hidden'}>Edit endless progression</button><label class="field-label">Run seed<input id="challenge-seed" type="number" min="0" max="4294967295" step="1" value="${seed}"></label><p class="fine-print">The same seed repeats the pieces and attack schedule.</p><div class="challenge-best">Your best <strong>${Number(bests[key()]??0).toLocaleString()}</strong></div><button class="primary" id="start-challenge">${players===1?'Start challenge':'Start free-for-all'}</button></section><aside class="panel challenge-rules"><p class="eyebrow">SCORING</p><h2>Every break counts.</h2><p>10 points per block, plus 5 for each block beyond four. The total is multiplied by the combo stage.</p><div class="scoring-example"><strong>8 blocks × triple</strong><span>(80 + 20) × 3 = <b>300 points</b></span></div><details class="rules-more"><summary>Full rules</summary><p class="muted">Everyone gets the same attacks on the same clock. Each attack waits for that player's next placement, one per turn. Your breaks earn points; the challenge sends the attacks.</p><p class="muted">Highest score wins, even if you are knocked out first. Tied scores share a place. Two-minute rush ends at the bell or when everyone is out; endless survival ends when everyone is out.</p><p class="muted">Your controls and timing apply to every board. Bests are kept separately for each timing profile and difficulty. Breakers get more frequent as the pairs go on, the same for everyone. Endless settings can be changed in the Workshop.</p></details></aside></div><section class="challenge-history"><p class="eyebrow">RECENT RUNS</p>${history.length?'<div class="challenge-history-list">'+history.slice(0,5).map(r=>`<div><strong>${Number(r.score).toLocaleString()}</strong><span>${r.mode==='timed'?'Two-minute rush':'Endless survival'} · ${r.players===4?'Free-for-all':'Solo'}</span><small>Seed ${esc(r.seed)} · ${clock(r.elapsed)}</small></div>`).join('')+'</div>':'<p class="muted">Your first score starts here.</p>'}</section>`;
 for(const b of $$('[data-challenge-mode]'))b.onclick=()=>{seed=Number($('#challenge-seed').value)||0;mode=b.dataset.challengeMode;setup();};
 $('#challenge-pool').onclick=showPool;$('#challenge-progression').onclick=showProgression;$('#challenge-settings').onclick=()=>showSettings?.();$('#challenge-difficulty').onchange=e=>{difficulty=e.target.value;save('challenge-difficulty',difficulty);seed=Number($('#challenge-seed').value)||0;setup();};
 $('#challenge-players').onchange=e=>{seed=Number($('#challenge-seed').value)||0;players=Number(e.target.value);setup();};
 $('#start-challenge').onclick=()=>{const input=$('#challenge-seed');if(!input.checkValidity()||input.value===''){input.reportValidity();return;}seed=Number(input.value);start();};
 }
 const board=(e,mini=false)=>`<section class="challenge-board ${mini?'mini':''}" id="contestant-${e.id}"><div class="board-header"><div><strong>${e.name}${e.id?' · AI':''}</strong><span id="challenge-state-${e.id}">Ready</span></div><div class="next-piece"><span>NEXT</span><canvas id="challenge-next-${e.id}" aria-label="${e.name} next pair"></canvas></div></div><div class="board-frame"><canvas id="challenge-board-${e.id}" role="img" aria-label="${e.name} puzzle board"></canvas></div><div class="challenge-board-foot"><strong id="challenge-score-${e.id}">0</strong><span id="challenge-incoming-${e.id}">No incoming</span></div></section>`;
 function start(){stopWorkers();session++;runKey=null;runKey=key();run=createChallenge({seed,mode,players,rules:handlingRules(prefs.rules),pool:getPool(),progression:readProgression(read('endless-progression',null))});paused=false;finishedSaved=false;countdown=1200;acc=0;actions=[];held.clear();brains=run.entries.map(()=>({key:null,plan:null,at:0}));
 host.innerHTML=`<section class="room-heading game-heading"><div><p class="eyebrow">${players===4?'FREE-FOR-ALL':'SOLO CHALLENGE'} / ${mode==='timed'?'TWO-MINUTE RUSH':'ENDLESS SURVIVAL'}</p><h1 id="challenge-title">Find your rhythm.</h1></div><div class="match-tools"><span id="challenge-clock">${mode==='timed'?'2:00':'0:00'}</span><button id="challenge-pause" aria-label="Pause challenge">Ⅱ</button><button id="challenge-leave">Leave</button></div></section><div class="challenge-arena"><section class="table-surface challenge-main"><div class="challenge-hud"><div><span>SCORE</span><strong id="challenge-live-score">0</strong></div><div><span>BEST COMBO</span><strong id="challenge-combo">—</strong></div><div><span>NEXT ATTACK</span><strong id="challenge-hazard">—</strong></div></div><p class="challenge-stage-caption" id="challenge-stage-caption"></p><div class="challenge-playfield">${board(run.entries[0])}<div id="challenge-overlay" class="game-overlay"></div></div><div class="challenge-feedback" id="challenge-feedback" role="status">Same pieces. Same pressure.</div><div class="touch-controls challenge-touch"><button data-challenge-action="left" aria-label="Move left">←</button><button data-challenge-action="ccw" aria-label="Rotate counterclockwise">↶</button><button data-challenge-action="cw" aria-label="Rotate clockwise">↷</button><button data-challenge-action="right" aria-label="Move right">→</button><button data-challenge-action="drop">Drop</button></div></section><aside class="challenge-sidebar"><section class="panel"><p class="eyebrow">${players===4?'LIVE STANDINGS':'YOUR RUN'}</p><div id="challenge-standings"></div><div id="challenge-progression-live" class="progression-live"></div><div class="divider"></div><div class="challenge-run-details"><span>Pressure <b id="challenge-pressure">1</b></span><span>Blocks cleared <b id="challenge-blocks">0</b></span><span>Seed <b>${seed}</b></span></div></section>${players===4?'<div class="challenge-opponents">'+run.entries.slice(1).map(e=>board(e,true)).join('')+'</div>':'<section class="panel"><p class="eyebrow">CHASE YOUR BEST</p><h2>'+Number(bests[key()]??0).toLocaleString()+'</h2><p class="muted">10 points per block + larger-clear bonus, multiplied by your combo.</p><p class="fine-print">Random attacks wait for your next placement. Keep column 4 open.</p></section>'}</aside></div><section id="challenge-results" aria-live="polite"></section><p class="fine-print challenge-control-note">Uses your configured controls. Pause with ${esc(String([].concat(prefs.keys.pause)[0]??'Esc').replace('Escape','Esc'))}. Seed ${seed} · rules v3 · ${fallSummary(run.entries[0].game.rules)}.</p>`;
 $('#challenge-pause').onclick=()=>pause();$('#challenge-leave').onclick=()=>{if(run.finished)return setup();pause(true);const A=globalThis.scrapsAsk;if(A)A({title:'Leave this run?',body:'Unfinished scores are not saved.',yes:'Leave run'}).then(ok=>{if(ok)setup();});else if(confirm('Leave this run? Unfinished scores are not saved.'))setup();};
 for(const b of $$('[data-challenge-action]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);press('touch-'+b.dataset.challengeAction,b.dataset.challengeAction);};b.onpointerup=b.onpointercancel=()=>release('touch-'+b.dataset.challengeAction);}
 for(let i=1;i<players;i++){try{const worker=new Worker('/ai-worker.js',{type:'module'});workers[i]=worker;worker.onmessage=({data})=>{const b=brains[i];if(data.id===b.key){if(data.error){worker.terminate();workers[i]=null;b.key=null;}else b.plan=[...(data.plan?.path??[]),'fastOn'];}};worker.onerror=()=>{worker.terminate();workers[i]=null;brains[i].key=null;};}catch{brains[i].plan=['fastOn'];}}
 sound('start');
 }
 function press(code,action){if(!run||run.finished)return;if(action==='pause'){pause();return;}if(countdown>0||paused||run.entries[0].game.players[0].dead)return;held.set(code,{action,next:run.elapsed+run.entries[0].game.rules.repeatDelayMs});actions.push({side:0,action:action==='drop'?'fastOn':action});if(['left','right','cw','ccw'].includes(action))sound(action==='cw'||action==='ccw'?'rotate':'move');}
 function release(code){const h=held.get(code);held.delete(code);if(h?.action==='drop'&&run&&!run.finished)actions.push({side:0,action:'fastOff'});}
 function releaseAll(){held.clear();actions=[];if(run&&!run.finished)actions.push({side:0,action:'fastOff'});}
 function pause(force){if(!run||run.finished)return;paused=force??!paused;releaseAll();set('#challenge-pause',paused?'▶':'Ⅱ');$('#challenge-pause').setAttribute('aria-label',paused?'Resume challenge':'Pause challenge');const overlay=$('#challenge-overlay');overlay.classList.toggle('shown',paused);overlay.innerHTML=paused?'<div class="pause-card"><h2>Run paused.</h2><button class="primary" id="challenge-resume">Back to it</button></div>':'';$('#challenge-resume')?.addEventListener('click',()=>pause(false));}
 function think(){for(let i=1;i<run.entries.length;i++){const p=run.entries[i].game.players[0],b=brains[i],opponent=botProfile(difficulty,i-1);if(p.dead||p.phase!=='fall')continue;const id=session+':'+p.nextIndex;if(id!==b.key){b.key=id;b.plan=workers[i]?null:[...planMove({board:p.board,active:p.active,nextPair:challengePair(seed,p.nextIndex,run.progression),opponent:{...opponent,depth:1}}).path,'fastOn'];b.at=run.elapsed+opponent.think;workers[i]?.postMessage({id,board:p.board,active:p.active,nextPair:challengePair(seed,p.nextIndex,run.progression),opponent});}if(b.plan?.length&&run.elapsed>=b.at){actions.push({side:i,action:b.plan.shift()});b.at=run.elapsed+opponent.actionMs;}}}
 function tick(){if(!run||paused||run.finished)return;if(countdown>0){countdown-=DT;const overlay=$('#challenge-overlay');overlay.classList.toggle('shown',countdown>0);overlay.innerHTML=countdown>0?'<div class="count-in">'+Math.ceil(countdown/400)+'</div>':'';return;}
 for(const h of held.values()){if(['left','right'].includes(h.action)&&run.elapsed>=h.next){actions.push({side:0,action:h.action});h.next=run.elapsed+run.entries[0].game.rules.repeatMs;}if(run.entries[0].game.version<10&&h.action==='drop'&&run.entries[0].game.players[0].phase==='fall'&&!run.entries[0].game.players[0].fast)actions.push({side:0,action:'fastOn'});}
 think();stepChallenge(run,DT,actions);actions=[];
 for(const e of run.events)if(e.side===0){if(e.type==='breaking')sound('clear',e.chain);else if(e.type==='hit')sound('hit');else if(e.type==='lock')sound('lock');}
 if(run.finished)finish();
 }
 function finish(){if(finishedSaved)return;finishedSaved=true;stopWorkers();held.clear();const e=run.entries[0],ranking=standings(run),rank=ranking.find(r=>r.id===0).rank;const old=Number(bests[key()]??0);bests[key()]=Math.max(old,e.score);history.unshift({mode,players,difficulty:players===4?difficulty:null,handling:run.entries[0].game.rules,version:3,progression:run.progression,seed,score:e.score,elapsed:run.elapsed,rank,date:Date.now()});history.splice(20);save('challenge-bests',bests);save('challenge-runs',history);
 set('#challenge-title',players===1?'Run complete.':rank===1?'Top of the table.':'The scores are in.');set('#challenge-pause','Ⅱ');$('#challenge-pause').disabled=true;sound(rank===1&&players===4?'win':'end');
 $('#challenge-results').innerHTML=`<div class="panel challenge-result-card"><div><p class="eyebrow">${e.score>old?'NEW PERSONAL BEST':run.reason==='time'?'TIME’S UP':'ALL BOARDS OUT'}</p><h2>${e.score.toLocaleString()} points${players===4?' · place '+rank:''}</h2><p class="muted">${e.blocks} blocks · best combo ×${e.bestCombo||1} · ${clock(e.deathAt??run.elapsed)} survived</p></div><div class="button-row"><button class="primary" id="challenge-retry">Same seed</button><button id="challenge-new">New seed</button><button id="challenge-back">Challenges</button></div></div>`;
 $('#challenge-retry').onclick=start;$('#challenge-new').onclick=()=>{seed=crypto.getRandomValues(new Uint32Array(1))[0];start();};$('#challenge-back').onclick=setup;$('#challenge-results').scrollIntoView({behavior:prefs.reduced?'instant':'smooth',block:'center'});
 }
 function render(time){if(!run){set('#challenge-pool-summary',getPool().map(p=>p.name).join(', '));set('.challenge-best strong',Number(bests[key()]??0).toLocaleString());return;}const human=run.entries[0];for(const e of run.entries){const p=e.game.players[0],rules=e.game.rules;drawBoard($('#challenge-board-'+e.id),p,{time,gravityMs:rules.gravityMs,fastFallMs:rules.fastFallMs,ghost:prefs.ghost,reduced:prefs.reduced,renderAheadMs:!paused&&!run.finished&&countdown<=0?acc:0});drawNext($('#challenge-next-'+e.id),challengePair(seed,p.nextIndex,run.progression));set('#challenge-score-'+e.id,e.score.toLocaleString());set('#challenge-state-'+e.id,p.dead?'OUT':e.lastClear&&run.elapsed-e.lastClear.at<1200?'+'+e.lastClear.points+' · ×'+e.lastClear.chain:'In play');set('#challenge-incoming-'+e.id,p.incoming.length?p.incoming.length+' waves queued · land a pair':'No queued attacks');$('#contestant-'+e.id).classList.toggle('eliminated',p.dead);}
 set('#challenge-clock',clock(mode==='timed'?TIMED_MS-run.elapsed:run.elapsed));set('#challenge-live-score',human.score.toLocaleString());set('#challenge-combo',human.bestCombo?'×'+human.bestCombo:'—');set('#challenge-hazard',run.finished?'—':clock(run.nextHazard.at-run.elapsed));set('#challenge-pressure',pressureAt(run.elapsed,run.progression).level);set('#challenge-blocks',human.blocks);
 const pressure=pressureAt(run.elapsed,run.progression),stage=pressure.stage,next=pressure.next,upcoming=run.nextHazard.attacks;const detail=upcoming.filter(a=>a.kind!=='sprinkle').map(a=>a.width+'×'+a.length+' sword').join(' + '),sprinkles=upcoming.find(a=>a.kind==='sprinkle')?.count??0;const preview=(detail?detail+' · ':'')+sprinkles+' sprinkles';
 set('#challenge-stage-caption',stage.name+(next?' · '+next.name+' in '+clock(pressure.remainingMs):' · final stage'));
 const progressHTML='<strong>'+esc(stage.name)+'</strong><p>Wave every ~'+stage.intervalSec+'s · '+stage.swords+' sword(s) '+stage.width+'×'+stage.length+' · '+stage.sprinkles+' sprinkles</p><p>Next wave: '+esc(preview)+' · '+esc(run.nextHazard.patternName)+'</p><p>'+(next?'Next: '+esc(next.name)+' in '+clock(pressure.remainingMs)+' · every '+next.intervalSec+'s, '+next.swords+' sword(s) '+next.width+'×'+next.length+', '+next.sprinkles+' sprinkles':'Final stage · this pressure continues')+'</p>';if($('#challenge-progression-live').innerHTML!==progressHTML)$('#challenge-progression-live').innerHTML=progressHTML;
 const queued=human.game.players[0].incoming.length;$('#challenge-hazard').classList.toggle('attack-warning',!run.finished&&run.nextHazard.at-run.elapsed<=3000);
 const ranking=standings(run),html=ranking.map(e=>`<div class="challenge-rank ${e.id===0?'is-you':''}"><span>${e.rank}</span><strong>${e.name}</strong><small>${e.dead?'OUT':run.finished?'FINISHED':'PLAYING'}</small><b>${e.score.toLocaleString()}</b></div>`).join('');if($('#challenge-standings').innerHTML!==html)$('#challenge-standings').innerHTML=html;
 set('#challenge-feedback',human.game.players[0].dead&&!run.finished?'You’re out. Watching the remaining boards—your score still counts.':human.lastClear&&run.elapsed-human.lastClear.at<1700?'+'+human.lastClear.points+' points · combo ×'+human.lastClear.chain:run.finished?'Run complete.':queued?queued+' attack wave(s) queued — land your next pair to receive one.':run.nextHazard.at-run.elapsed<=3000?'Incoming in '+clock(run.nextHazard.at-run.elapsed)+' · '+preview:`Pressure ${pressureAt(run.elapsed,run.progression).level} · ${Math.round(breakerRateAt(human.game.players[0].nextIndex,run.progression)*100)}% breakers`);
 }
 function frame(time){if(disposed)return;const elapsed=Math.min(100,time-(last||time));last=time;if(run&&!paused&&!run.finished){acc+=elapsed;while(acc>=DT){tick();acc-=DT;}}else acc=0;render(time);raf=requestAnimationFrame(frame);}
 window.addEventListener('keydown',e=>{if(!run||document.querySelector('dialog[open]')||document.activeElement?.matches('input,select,textarea'))return;const action=actionFor(prefs.keys,e.code);if(!action)return;e.preventDefault();if(!e.repeat)press(e.code,action);},{signal:lifecycle.signal});
 window.addEventListener('keyup',e=>release(e.code),{signal:lifecycle.signal});window.addEventListener('blur',()=>pause(true),{signal:lifecycle.signal});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause(true);},{signal:lifecycle.signal});
 setup();raf=requestAnimationFrame(frame);
 return {isActive:()=>!!run&&!run.finished,pause:()=>pause(true),getState:()=>run?{seed,mode,difficulty,rules:run.entries[0].game.rules,elapsed:run.elapsed,paused,finished:run.finished,hazards:run.hazards,stage:pressureAt(run.elapsed,run.progression),nextHazard:run.nextHazard,standings:standings(run),players:run.entries.map(e=>({id:e.id,pattern:e.patternName,stats:e.game.players[0].stats,attacksReceived:e.attacksReceived,turn:e.game.players[0].turn,score:e.score,board:structuredClone(e.game.players[0].board),active:structuredClone(e.game.players[0].active),queued:e.game.players[0].incoming.length}))}:null,destroy(){disposed=true;lifecycle.abort();stopWorkers();cancelAnimationFrame(raf);held.clear();}};
}
